export function errorText(code: string, lang: string = 'zh-TW'): string { return errorPairs[code]?.[lang === 'en' ? 1 : 0] ?? pairs[code]?.[lang === 'en' ? 1 : 0] ?? `${t('error', lang)} · ${code}` }
export function outputLanguage(explicit: string | undefined, interfaceLanguage: string): string { return explicit || interfaceLanguage }
export function move<T>(items: readonly T[], index: number, offset: number): T[] { const next = items.slice(); const target = index + offset; if (target < 0 || target >= next.length) return next; [next[index], next[target]] = [next[target], next[index]]; return next }
